using System.Collections.Concurrent;
using System.Text.Json;

namespace CombatSolver;

internal static class TaskSaturatedHistoryObservation
{
    private static int NextId;
    private sealed class Counts
    {
        internal readonly int Id = Interlocked.Increment(ref NextId);
        internal readonly Dictionary<StateFingerprint, StateFingerprint> First = new();
        internal long Calls, Changed, RawDuplicate, ProjectedDifferentRaw;
        internal int MaxStarts, MaxAttacks, MaxSeries;
        internal readonly List<object> Samples = new();
    }

    private static readonly ConcurrentDictionary<CombatBeamSolver, Counts> Items = new();

    private static readonly object ExportGate = new();
    private static object Capture(Counts c)
    {
        lock (c) return new {
            c.Id, c.Calls, c.Changed, c.RawDuplicate, c.ProjectedDifferentRaw,
            ProjectedKeys = c.First.Count, c.MaxStarts, c.MaxAttacks, c.MaxSeries,
            Samples = c.Samples.ToArray()
        };
    }

    internal static string Snapshot(CombatBeamSolver solver)
    {
        string json = Items.TryGetValue(solver, out Counts? c)
            ? JsonSerializer.Serialize(new[] { Capture(c) }) : "[]";
        if (Environment.GetEnvironmentVariable("TASK_SATURATED_HISTORY_OUT") is { } directory)
        {
            lock (ExportGate)
                File.WriteAllText(Path.Combine(directory, "all-members.json"),
                    JsonSerializer.Serialize(Items.Values.Select(Capture).ToArray()));
        }
        return json;
    }

    internal static void Record(CombatBeamSolver solver, StateFingerprint raw,
        StateFingerprint projected, int turn, int starts, int attacks, int series)
    {
        Counts c = Items.GetOrAdd(solver, static _ => new());
        lock (c)
        {
            c.Calls++;
            if (raw != projected) c.Changed++;
            c.MaxStarts = Math.Max(c.MaxStarts, starts);
            c.MaxAttacks = Math.Max(c.MaxAttacks, attacks);
            c.MaxSeries = Math.Max(c.MaxSeries, series);
            if (!c.First.TryGetValue(projected, out StateFingerprint previous))
                c.First.Add(projected, raw);
            else if (previous == raw)
                c.RawDuplicate++;
            else
            {
                c.ProjectedDifferentRaw++;
                if (c.Samples.Count < 8)
                    c.Samples.Add(new { turn, starts, attacks, series, raw, projected, previous });
            }
        }
    }
}

